"""Static HTML composition. Merchant text is escaped; layouts share semantic controls."""
from html import escape as esc
from urllib.parse import quote
import json

def icon(name, size=22):
    paths={'bag':'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M9 8V6a3 3 0 0 1 6 0v2"/>','arrow':'<path d="M4 12h15M13 5l7 7-7 7"/>','search':'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>','check':'<path d="m5 12 4 4L19 6"/>','leaf':'<path d="M20 4C8 2 2 9 7 16s15 1 13-12Z"/><path d="m5 21 12-13"/>','mail':'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>','lock':'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>','menu':'<path d="M4 6h16M4 12h16M4 18h16"/>'}
    return f'<svg width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{paths[name]}</svg>'

def money(p):
    return 'Free' if p['amount_minor']==0 else f"${p['amount_minor']/100:.2f}"

def card(p, base):
    url=base+'products/'+p['slug']+'/'
    return f'''<article class="product-card" data-key="{esc(p['product_key'])}" data-category="{esc(p['category'])}">
      <a class="product-art" href="{url}" tabindex="-1" aria-hidden="true"><img src="{base+p['image']}" alt="" width="800" height="720" loading="lazy"></a>
      <div class="product-copy"><p class="eyebrow">{esc(p['eyebrow'])}</p><h3><a href="{url}">{esc(p['title'])}</a></h3><p class="description">{esc(p['short_description'])}</p>
      <div class="product-bottom"><span class="price">{money(p)}<small>{esc(p['currency']) if p['amount_minor'] else 'digital guide'}</small></span><button type="button" class="add-small" data-add="{esc(p['product_key'])}" aria-label="Add {esc(p['title'])} to cart">Add to cart <span aria-hidden="true">+</span></button></div></div></article>'''

def search(base, label='Search products', value=''):
    return f'''<form class="search-form" action="{base}shop/" role="search"><label class="sr-only" for="site-search">{label}</label><input id="site-search" name="q" type="search" placeholder="Search the collection" value="{esc(value)}" maxlength="100"><button aria-label="Search" type="submit">{icon('search')}</button></form>'''

def header(gel, theme, base, preview):
    i=gel['identity']; logo=f'''<a class="brand" href="{base}" aria-label="{esc(i['name'])} — home"><img src="{base+gel['assets']['logo']}" width="38" height="38" alt=""><span>{esc(i['short_name'])}<small>{esc(i['wordmark_descriptor'])}</small></span></a>'''
    nav=f'''<nav class="desktop-nav" aria-label="Main navigation"><a href="{base}shop/">Shop all</a><a href="{base}#our-story">Our story</a><a href="{base}help/">Help & care</a></nav>'''
    cart=f'''<a class="header-cart" href="{base}cart/" aria-label="Your cart"><span class="cart-label">Cart</span>{icon('bag')}<span data-cart-count class="cart-count">0</span></a>'''
    mobile=f'''<details class="mobile-nav"><summary aria-label="Open navigation">{icon('menu')}</summary><nav aria-label="Mobile navigation"><a href="{base}shop/">Shop all</a><a href="{base}#our-story">Our story</a><a href="{base}help/">Help & care</a></nav></details>'''
    if theme=='classic':
        head=f'<div class="masthead wrap">{logo}{search(base)}{cart}{mobile}</div><div class="navigation-bar"><div class="wrap">{nav}<span class="navigation-note">{esc(i["tagline"])}</span></div></div>'
    else: head=f'<div class="masthead wrap">{logo}{nav}{cart}{mobile}</div>'
    bar=f'''<div class="preview-bar"><span>INTERACTIVE PREVIEW · No payments or emails</span><a href="{base}../">{'Preview home' if base=='/' else 'Theme gallery'} {icon('arrow',14)}</a></div>''' if preview else ''
    return f'<a class="skip-link" href="#main">Skip to content</a>{bar}<header class="site-header">{head}</header>'

def hero(gel,theme,base):
    h=gel['hero']; a=gel['assets']; title=esc(h['title']).replace('\n','<br>')
    text=f'''<div class="hero-copy"><p class="eyebrow">{esc(h['eyebrow'])}</p><h1>{title}</h1><p class="hero-description">{esc(h['body'])}</p><a class="button" href="{base}shop/">{esc(h['cta'])}{icon('arrow')}</a><p class="hero-note">{icon('leaf',18)} {esc(gel['identity']['tagline'])}</p></div>'''
    art=f'''<figure class="hero-art"><img src="{base+a['hero']}" alt="{esc(a['hero_alt'])}" width="800" height="720" fetchpriority="high"><figcaption><span>01 / THE EVERYDAY COLLECTION</span><span>Thoughtfully simple.</span></figcaption></figure>''' if 'hero' in a else ''
    return f'<section class="hero wrap">{text}{art}</section>'

def filters(products):
    cats=list(dict.fromkeys(p['category'] for p in products))
    return '<div class="category-filters" role="group" aria-label="Filter by category"><button class="filter-button" data-category-filter="all" aria-pressed="true">All products <span>'+str(len(products))+'</span></button>'+''.join(f'<button class="filter-button" data-category-filter="{esc(c)}" aria-pressed="false">{esc(c)} <span>{sum(p["category"]==c for p in products)}</span></button>' for c in cats)+'</div>'

def collection(gel, products, theme, base, shop=False):
    top=f'''<div class="section-heading"><div><p class="eyebrow">{'THE COLLECTION' if shop else 'SIMPLE THINGS. GOOD BEGINNINGS.'}</p><h{1 if shop else 2}>{'Shop the collection' if shop else 'Find your next little thing.'}</h{1 if shop else 2}></div>{'<a class="text-link" href="'+base+'shop/">Explore everything '+icon('arrow',18)+'</a>' if not shop else ''}</div>'''
    controls=f'''<div class="catalogue-tools">{filters(products)}<label class="sort-label">Sort by <select id="sort"><option value="featured">Featured</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option><option value="name">Name</option></select></label></div>'''
    return f'''<section class="collection wrap">{top}{search(base) if shop and theme!='classic' else ''}<div class="catalogue-layout">{controls}<div><p id="results-status" class="results-status" role="status" aria-live="polite">{len(products)} products</p><div id="products" class="product-grid">{''.join(card(p,base) for p in products)}</div><div id="no-results" class="empty-state" hidden><h2>No little things found.</h2><p>Try another search or show the whole collection.</p><button type="button" id="reset-filter">Clear filters</button></div></div></div></section>'''

def story(gel,base):
    return f'''<section id="our-story" class="story wrap"><div><p class="eyebrow">A SMALL STORE, BY DESIGN</p><h2>Fewer things.<br>More thought.</h2></div><div><p>{esc(gel['identity']['description'])}</p><p>Browse at your pace. Choose what suits you. No account to create, no noisy extras.</p><a class="text-link" href="{base}help/">A little help along the way {icon('arrow',18)}</a></div></section>'''

def product_page(gel,p,base,preview):
    specs=''.join(f'<div><dt>{esc(k)}</dt><dd>{esc(v)}</dd></div>' for k,v in p['specs'].items())
    public_reviews=f'''<section class="public-reviews wrap" id="reviews" aria-labelledby="reviews-heading"><div class="section-heading"><div><p class="eyebrow">FROM PEOPLE WHO CHOSE IT</p><h2 id="reviews-heading">Customer reviews</h2></div><span class="tag">{'Preview data' if preview else 'Customer experiences'}</span></div><p id="reviews-status" role="status" aria-live="polite">{'Illustrative review only — not a real customer rating.' if preview else ''}</p><div id="review-list">{('<article class="quote-card"><span class="stars" aria-label="5 out of 5 stars">★★★★★</span><h3>A lovely little beginning</h3><p>“A simple project to slow down with. The instructions made getting started feel easy.”</p><p class="muted">Alex · Sample reviewer</p></article>') if preview else ''}</div><button id="reviews-more" type="button" hidden>Load more reviews</button></section>''' if p.get('review_subject') else ''
    return f'''<div class="wrap breadcrumb"><a href="{base}shop/">The collection</a><span aria-hidden="true">/</span><span>{esc(p['title'])}</span></div><section class="product-detail wrap"><figure class="detail-art"><img src="{base+p['image']}" alt="{esc(p['image_alt'])}" width="800" height="720"></figure><div class="detail-copy"><p class="eyebrow">{esc(p['eyebrow'])}</p><h1>{esc(p['title'])}</h1><p class="detail-price">{money(p)} <small>{esc(p['currency']) if p['amount_minor'] else 'digital guide'}</small></p><p class="lead">{esc(p['short_description'])}</p><p>{esc(p['details'])}</p><ul class="feature-list">{''.join('<li>'+icon('check',18)+esc(x)+'</li>' for x in p['features'])}</ul><button type="button" class="button wide" data-add="{esc(p['product_key'])}">Add to cart {icon('bag')}</button><p class="muted small">{'Sample product, price and illustration.' if preview else 'Final price and availability are confirmed at checkout.'}</p><details class="product-info"><summary>The details</summary><dl>{specs}</dl></details><details class="product-info"><summary>A little help</summary><p>Questions before you choose? <a href="{base}help/">Get in touch with the store.</a></p></details></div></section>{public_reviews}'''

def page_shell(gel,theme,base,page,title,content,preview=True,product_key=''):
    name=gel['identity']['name']
    footer=f'''<footer class="site-footer"><div class="wrap footer-grid"><div><img class="footer-mark" src="{base+gel['assets']['logo_inverse']}" width="44" height="44" alt=""><p class="footer-name">{esc(gel['identity']['short_name'])}</p><p>{esc(gel['identity']['tagline'])}</p></div><nav aria-label="Footer"><a href="{base}shop/">The collection</a><a href="{base}help/">Contact & care</a><a href="{base}help/#privacy">Privacy</a></nav><div><p class="eyebrow">HERE TO HELP</p><a href="mailto:{esc(gel['identity']['contact_email'])}">{esc(gel['identity']['contact_email'])}</a><p class="small">{'Fictional store · illustrative products' if preview else 'Thank you for shopping with us.'}</p></div></div><div class="wrap footer-bottom"><span>{esc(name)}</span><span>{esc(gel['identity']['currency'])} · {esc(gel['identity']['locale'])}</span></div></footer>'''
    preview_tools=f'''<details class="preview-tools"><summary>Preview journeys & states</summary><nav aria-label="Preview states"><a href="{base}cart/">Cart</a><a href="{base}inbox/">Sample invitation email</a><a href="{base}review/">Review two products</a><a href="{base}review/manage.html">Edit / withdraw a review</a><a href="{base}unsubscribe/">Unsubscribe</a>{''.join(f'<a href="{base}purchase-return/?state={s}">Return: {s}</a>' for s in ('confirmed','pending','unavailable','cancelled','expired'))}<a href="{base}review/?state=unavailable">Review unavailable</a><a href="{base}review/?state=expired">Invalid invitation</a><button type="button" data-reset-demo>Reset preview data</button></nav></details>''' if preview else ''
    return f'''<!doctype html><html lang="{esc(gel['identity']['locale'])}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="referrer" content="no-referrer">{('<meta name="robots" content="noindex,nofollow">') if preview or page in ('review','manage','purchase-return','cart','unsubscribe') else ''}<title>{esc(title)} · {esc(name)}</title><meta name="description" content="{esc(gel['identity']['description'])}"><link rel="icon" href="{base+gel['assets']['favicon']}" type="image/svg+xml"><link rel="stylesheet" href="{base}theme/tokens.css"><link rel="stylesheet" href="{base}theme/base.css"><link rel="stylesheet" href="{base}theme/theme.css"><script src="{base}site-config.js" defer></script><script type="module" src="{base}theme/app.mjs"></script></head><body class="theme-{theme} page-{page}" data-page="{page}" data-product-key="{esc(product_key)}">{header(gel,theme,base,preview)}<main id="main" tabindex="-1">{content}</main><div id="toast" class="toast" role="status" aria-live="polite" aria-atomic="true"></div>{preview_tools}{footer}<noscript><p class="noscript">You can browse the collection without JavaScript. Cart, checkout and review forms require JavaScript.</p></noscript><dialog id="confirm-dialog" aria-labelledby="dialog-title"><h2 id="dialog-title">Withdraw this review?</h2><p>Your review will no longer be displayed. This does not change your order.</p><div class="button-row"><button type="button" data-dialog-cancel autofocus>Keep my review</button><button type="button" class="danger" data-dialog-confirm>Withdraw review</button></div></dialog></body></html>'''

def simple_page(page,gel,base):
    titles={'cart':('YOUR LITTLE COLLECTION','Your cart','Take a moment. Make it yours.'),'checkout-preview':('PREVIEW ONLY','On to secure checkout','In a connected store, CartRay sends you to Stripe to pay.'),'purchase-return':('YOUR PURCHASE','Checking your order…',''),'review':('YOUR EXPERIENCE MATTERS','How was it?','A rating, a few words, or both. Your honest experience helps the next person choose.'),'manage':('YOUR WORDS. YOUR CHOICE.','Manage your review','Correct your experience or withdraw your review.'),'unsubscribe':('YOUR EMAIL PREFERENCES','A little less in your inbox.','Stop review-request emails from this store. Your purchase is unaffected.'),'inbox':('SAMPLE EMAIL','One small invitation.','A purchase-scoped invitation, not a newsletter subscription.')}
    eye,title,sub=titles[page]
    return f'<section class="flow-page wrap"><header class="flow-heading"><p class="eyebrow">{eye}</p><h1>{title}</h1><p>{sub}</p></header><p id="message" class="message" role="status" aria-live="polite"></p><div id="content"><p>Loading…</p></div></section>'

def help_page(gel,base,preview):
    return f'''<section class="flow-page wrap"><p class="eyebrow">HERE TO HELP</p><h1>A little help<br>along the way.</h1><div class="help-grid"><article class="panel"><h2>Talk to the store</h2><p>Questions about a product or your order?</p><a href="mailto:{esc(gel['identity']['contact_email'])}">{esc(gel['identity']['contact_email'])}</a>{'<p class="muted">This is a fictional preview address.</p>' if preview else ''}</article><article class="panel"><h2>Checkout & your order</h2><p>There is no customer account to create. In a connected store, payment happens on Stripe. A return page does not by itself confirm payment.</p></article><article class="panel"><h2>Review invitations</h2><p>The checkout choice is for one review request about your purchase. You can untick it before payment, or unsubscribe using the email link.</p></article><article class="panel" id="privacy"><h2>Privacy</h2><p>{'This preview stores only demo cart and review data in your browser. It sends no data to a merchant. Use “Reset preview data” to clear it.' if preview else 'Contact the store for its published privacy policy and information about your purchase data.'}</p><p>Review access comes from your purchase-specific email link, not from an email address typed into this page.</p></article></div></section>'''
